"""Produits Mère Martine complémentaires : un produit par ligne « Achat/produit » du fichier « produit martine ».

image None = visuel « étiquette d'atelier » généré (build/labels.py), remplaçable par une photo
déposée dans site/assets/img/martine/<slug>.webp.
Les coffrets (image « mosaique ») sont composés à partir des visuels de leur contenu ; leur prix
est calculé à -15 % de la somme des produits.
"""


def P(slug, nom, cat, prix, contenance, etiquette, palette, accroche, description, bienfaits, utilisation, composition,
      lies, guide, mots_cles, aussi=(), variantes=None, image=None, contenu=None):
    d = {
        "slug": slug, "nom": nom, "categorie": cat, "aussi": list(aussi), "prix": prix, "contenance": contenance,
        "etiquette": etiquette, "palette": palette, "accroche": accroche, "description": description,
        "bienfaits": bienfaits, "utilisation": utilisation, "composition": composition, "lies": lies,
        "guide": guide, "mots_cles": mots_cles, "image": image,
    }
    if variantes:
        d["variantes"] = variantes
    if contenu:
        d["contenu"] = contenu
    return d


